CREATE TABLE finfolk.data_sources (id text NOT NULL, metadata jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY (id));
CREATE TABLE finfolk.depth_datasets (id text NOT NULL, source_id text NOT NULL, upstream_id text NOT NULL, version text NOT NULL, checksum text NOT NULL, status text NOT NULL DEFAULT 'staged'::text, metadata jsonb NOT NULL, PRIMARY KEY (id), FOREIGN KEY (source_id) REFERENCES finfolk.data_sources(id), UNIQUE (source_id, upstream_id, version), CHECK ((status = ANY (ARRAY['staged'::text, 'published'::text, 'superseded'::text]))));
CREATE TABLE finfolk.site_depth_datasets (revision_id uuid NOT NULL, dataset_id text NOT NULL, relationship text NOT NULL, evidence jsonb NOT NULL, PRIMARY KEY (revision_id, dataset_id), FOREIGN KEY (revision_id) REFERENCES finfolk.site_revisions(id) ON DELETE CASCADE, FOREIGN KEY (dataset_id) REFERENCES finfolk.depth_datasets(id), CHECK ((relationship = ANY (ARRAY['candidate'::text, 'confirmed'::text]))));
CREATE TABLE finfolk.tide_stations (id text NOT NULL, source_id text NOT NULL, upstream_id text NOT NULL, metadata jsonb NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY (id), FOREIGN KEY (source_id) REFERENCES finfolk.data_sources(id), UNIQUE (source_id, upstream_id));
CREATE TABLE finfolk.site_tide_stations (revision_id uuid NOT NULL, station_id text NOT NULL, evidence jsonb NOT NULL, PRIMARY KEY (revision_id), FOREIGN KEY (revision_id) REFERENCES finfolk.site_revisions(id) ON DELETE CASCADE, FOREIGN KEY (station_id) REFERENCES finfolk.tide_stations(id));
CREATE TABLE finfolk.environment_targets (id text NOT NULL, source_id text NOT NULL, product text NOT NULL, configuration jsonb NOT NULL, last_requested_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id), FOREIGN KEY (source_id) REFERENCES finfolk.data_sources(id), CHECK ((product = ANY (ARRAY['weather'::text, 'marine'::text, 'tides'::text]))));
CREATE TABLE finfolk.environment_snapshots (id uuid NOT NULL DEFAULT gen_random_uuid(), target_id text NOT NULL, issued_at timestamptz, retrieved_at timestamptz NOT NULL DEFAULT now(), valid_from timestamptz NOT NULL, valid_to timestamptz NOT NULL, fresh_until timestamptz NOT NULL, delete_after timestamptz NOT NULL, checksum text NOT NULL, schema_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, PRIMARY KEY (id), FOREIGN KEY (target_id) REFERENCES finfolk.environment_targets(id) ON DELETE CASCADE, CHECK ((valid_to > valid_from)), CHECK ((delete_after >= retrieved_at)), CHECK ((schema_version > 0)));
CREATE TABLE finfolk.environment_jobs (target_id text NOT NULL, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_token uuid, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, last_success timestamptz, error_code text, PRIMARY KEY (target_id), FOREIGN KEY (target_id) REFERENCES finfolk.environment_targets(id) ON DELETE CASCADE, CHECK ((attempts >= 0)), CHECK (((lease_token IS NULL) = (lease_until IS NULL))));
REVOKE ALL ON finfolk.data_sources, finfolk.depth_datasets, finfolk.site_depth_datasets, finfolk.tide_stations, finfolk.site_tide_stations, finfolk.environment_targets, finfolk.environment_snapshots, finfolk.environment_jobs FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE,DELETE ON finfolk.data_sources, finfolk.depth_datasets, finfolk.site_depth_datasets, finfolk.tide_stations, finfolk.site_tide_stations, finfolk.environment_targets, finfolk.environment_snapshots, finfolk.environment_jobs TO finfolk_api;
CREATE INDEX environment_snapshot_target ON finfolk.environment_snapshots USING btree (target_id, retrieved_at DESC);
CREATE INDEX environment_snapshot_retention ON finfolk.environment_snapshots USING btree (delete_after);
CREATE INDEX environment_job_due ON finfolk.environment_jobs USING btree (next_attempt_at);
